 function plant(){const cap=level().slots+(state.upgrades.includes('shelf')?2:0)+(state.crew.includes('helper')?1:0);if(state.plants.length>=cap){toast('No room for another cutting. Try an upgrade.');return}if(state.cash<12){toast('You need $12 for a cutting.');return}state.cash-=12;state.plants.push({progress:0,quality:48+Math.floor(Math.random()*14)});toast('Cutting planted. Keep an eye on it.');render()}
 function harvest(){const ready=state.plants.filter(p=>p.progress>=1);if(!ready.length){toast('Nothing ready just yet. Give them a little time.');return}let q=0;ready.forEach(p=>{q+=p.quality+(state.upgrades.includes('soil')?12:0)});state.stock+=ready.length;state.quality=Math.round((state.quality*Math.max(0,state.stock-ready.length)+q)/state.stock);state.plants=state.plants.filter(p=>p.progress<1);state.actions++;toast(`${ready.length} fresh ${ready.length===1?'pack':'packs'} added to inventory.`);if(state.actions%4===0)state.day++;render()}
 function sell(){currentOrder();const o=state.order;if(state.stock<o.need){toast('Not enough in stock for this request.');return}if(state.quality<o.quality){toast('This customer is looking for a higher quality.');return}let bonus=state.upgrades.includes('manager')?Math.round(o.reward*.15):0;state.stock-=o.need;state.cash+=o.reward+bonus;state.rep+=5+(state.upgrades.includes('sign')?3:0);state.heat=Math.min(maxHeat,state.heat+(state.fronts.includes('ledger')?1:4));state.order=null;state.day+=Math.random()>.55?1:0;toast(`Deal done. +$${o.reward+bonus} · reputation up.`);currentOrder();render()}
 function buy(id,cost,group){if(state.upgrades.includes(id)||state.crew.includes(id)||state.fronts.includes(id))return;if(state.cash<cost){toast('Not enough cash for that yet.');return}state.cash-=cost;if(group==='crew')state.crew.push(id);else if(group==='front')state.fronts.push(id);else state.upgrades.push(id);if(id==='helper')state.rep+=5;toast('Investment made. Your operation grows.');render()}
-function expand(){const p=properties[state.stage+1];if(!p||state.cash<p.price)return;state.cash-=p.price;state.stage++;state.day+=3;state.heat=Math.min(maxHeat,state.heat+8);toast(`Welcome to ${p.name}. New chapter unlocked.`);render()}
