import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime = `${process.env.HOME}/.local/share/omgithub-playwright`;
const require = createRequire(`${runtime}/package.json`);
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(`${runtime}/linux.json`, 'utf8'));
const browser = await chromium.launch(config.browser.launchOptions);
try {
 const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
 const errors=[]; page.on('pageerror', e=>errors.push(e.message));
 await page.goto('http://127.0.0.1:3002/', {waitUntil:'load'});
 await page.locator('#storyBtn').click();
 if (!(await page.locator('#modalBack').evaluate(el=>el.classList.contains('open')))) throw new Error('Story modal did not open');
 await page.locator('#modalChoices button').first().click();
 if ((await page.locator('#missionNo').textContent()).trim() !== '02') throw new Error('Story did not advance to chapter 02');
 await page.evaluate(()=>{localStorage.removeItem('greenEmpireSave'); location.reload()});
 await page.waitForLoadState('load');
 const cost = await page.locator('#upgradeList .upgrade').first().locator('.cost').textContent();
 if (!cost.includes('650')) throw new Error(`Unexpected expansion cost: ${cost}`);
 await page.evaluate(()=>{const s=JSON.parse(localStorage.getItem('greenEmpireSave')||'{}');s.cash=650;localStorage.setItem('greenEmpireSave',JSON.stringify(s));location.reload()});
 await page.waitForLoadState('load');
 await page.locator('#upgradeList .upgrade').first().click();
 if ((await page.locator('#propertyTitle').textContent()).trim() !== 'Marlow’s Garage') throw new Error('Expansion did not advance property');
 if(errors.length) throw new Error(errors.join('; '));
 console.log('PASS: story modal/choice, $650 expansion cost, expansion flow, no page errors.');
} finally { await browser.close(); }
EOF

